import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../app/providers.dart';import '../../shared/widgets.dart';
class DashboardScreen extends ConsumerWidget{const DashboardScreen({super.key});@override Widget build(BuildContext c,WidgetRef ref){final state=ref.watch(dashboardProvider);return RefreshIndicator(onRefresh:()=>ref.refresh(dashboardProvider.future),child:CustomScrollView(slivers:[SliverPadding(padding:const EdgeInsets.all(16),sliver:SliverToBoxAdapter(child:Text('Dashboard',style:Theme.of(c).textTheme.headlineSmall))),state.when(loading:()=>const SliverFillRemaining(child:LoadingPanel()),error:(e,s)=>SliverFillRemaining(child:ErrorPanel('Unable to load your dashboard.',onRetry:()=>ref.invalidate(dashboardProvider))),data:(data){final cards=[('Assigned work orders','assigned_work_orders','/work-orders'),('Pending approvals','pending_approvals','/work-orders'),('Overdue work orders','overdue_work_orders','/work-orders'),('Low-stock alerts','low_stock_alerts','/dashboard'),('Maintenance reviews','pending_maintenance_reviews','/maintenance'),('Corrective actions','assigned_corrective_actions','/dashboard'),('Unread notifications','unread_notifications','/notifications')].where((e)=>data.values.containsKey(e.$2)).toList();if(cards.isEmpty)return const SliverFillRemaining(child:EmptyPanel('No dashboard items are assigned to you.'));return SliverPadding(padding:const EdgeInsets.symmetric(horizontal:16),sliver:SliverGrid(gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:260,mainAxisExtent:125,crossAxisSpacing:12,mainAxisSpacing:12),delegate:SliverChildBuilderDelegate((c,i){final item=cards[i];return SummaryCard(label:item.$1,value:data[item.$2],onTap:()=>c.go(item.$3));},childCount:cards.length)));})]));}}
